// Pick a provider (Ollama -> Anthropic -> OpenAI -> heuristic) and build the request.
const cfg = $('Config').first().json;
const tr = $('Transcribe (yt-dlp + Whisper)').first().json;
const probe = $input.first().json || {};

const SYSTEM = `You turn transcripts of short tech videos (Instagram reels) into study notes.
Return ONLY a JSON object, no prose, matching exactly this shape:
{
  "title": "short descriptive title, max 80 chars",
  "summary": "3-5 sentence recap of what the video teaches",
  "concepts": [{"name": "concept", "explanation": "one sentence"}],
  "codeSnippets": [{"language": "python", "code": "...", "description": "what it does"}],
  "steps": ["ordered step the viewer should follow"],
  "links": [{"url": "https://...", "label": "what it is"}],
  "topics": ["2-6 broad lowercase topics, e.g. 'react', 'system design', 'llms'"]
}
Rules:
- Only include code that is actually shown or dictated; make it runnable when the intent is clear.
- Only include links that are explicitly mentioned. Never invent URLs.
- Use empty arrays when something is absent.
- If the transcript is thin, lean on the caption.`;

const parts = [];
if (tr.title) parts.push(`VIDEO TITLE: ${String(tr.title).slice(0, 200)}`);
if (tr.caption) parts.push(`CAPTION:\n${String(tr.caption).slice(0, 2000)}`);
parts.push(`TRANSCRIPT:\n${String(tr.transcript || '').slice(0, 12000) || '(no speech detected)'}`);
const user = parts.join('\n\n');

const models = Array.isArray(probe.models) ? probe.models.map(m => m.model || m.name || '') : [];
const base = cfg.ollamaModel.split(':')[0];
const ollamaReady = models.some(n => n === cfg.ollamaModel || n.split(':')[0] === base);
const ollamaNote = probe.error ? 'ollama unreachable' : (ollamaReady ? 'ollama ready' : `ollama up but ${cfg.ollamaModel} not pulled`);

const want = cfg.llmProvider;
let provider = 'heuristic';
if ((want === 'auto' || want === 'ollama') && ollamaReady) provider = 'ollama';
else if ((want === 'auto' || want === 'anthropic') && cfg.hasAnthropic) provider = 'anthropic';
else if ((want === 'auto' || want === 'openai') && cfg.hasOpenAI) provider = 'openai';

let llmUrl = null, llmBody = null, model = null;
if (provider === 'ollama') {
  model = cfg.ollamaModel;
  llmUrl = `${cfg.ollamaUrl}/api/chat`;
  llmBody = { model, stream: false, format: 'json', options: { temperature: 0.2, num_ctx: 8192 },
    messages: [{ role: 'system', content: SYSTEM }, { role: 'user', content: user }] };
} else if (provider === 'anthropic') {
  model = cfg.anthropicModel;
  llmUrl = 'https://api.anthropic.com/v1/messages';
  llmBody = { model, max_tokens: 4096, system: SYSTEM, messages: [{ role: 'user', content: user }] };
} else if (provider === 'openai') {
  model = cfg.openaiModel;
  llmUrl = 'https://api.openai.com/v1/chat/completions';
  llmBody = { model, temperature: 0.2, response_format: { type: 'json_object' },
    messages: [{ role: 'system', content: SYSTEM }, { role: 'user', content: user }] };
}

return [{ json: { provider, model, llmUrl, llmBody, ollamaNote } }];

// Tolerant JSON parsing of the model output; heuristic fallback if anything is off.
const b = $('Build LLM request').first().json;
const tr = $('Transcribe (yt-dlp + Whisper)').first().json;
const res = b.provider === 'heuristic' ? null : ($input.first().json || {});

function firstObject(text) {
  let start = text.indexOf('{');
  while (start !== -1) {
    let depth = 0, inStr = false, esc = false;
    for (let i = start; i < text.length; i++) {
      const ch = text[i];
      if (inStr) { if (esc) esc = false; else if (ch === '\\') esc = true; else if (ch === '"') inStr = false; }
      else if (ch === '"') inStr = true;
      else if (ch === '{') depth++;
      else if (ch === '}') { depth--; if (depth === 0) return text.slice(start, i + 1); }
    }
    start = text.indexOf('{', start + 1);
  }
  return null;
}
function parse(raw) {
  let t = String(raw || '').trim().replace(/^```(?:json)?\s*|\s*```$/gm, '').trim();
  const cand = t.startsWith('{') ? t : firstObject(t);
  if (!cand) throw new Error('no JSON object in model output');
  try { return JSON.parse(cand); } catch (e) { return JSON.parse(cand.replace(/,\s*([}\]])/g, '$1')); }
}
const STOP = new Set('the a an and or but if then so to of in on for with is are was were be been this that it its you your we our i my me they them at by from as not no do does did can will just like get got use using how what why when here there about into out up down one two all any some more most very really also only than too'.split(' '));
function heuristic() {
  const caption = String(tr.caption || '');
  const text = [caption, tr.transcript || ''].filter(Boolean).join(' ').trim();
  const sentences = text.split(/(?<=[.!?])\s+/);
  const freq = {};
  for (const w of (text.toLowerCase().match(/[a-z][a-z0-9+#.-]{2,}/g) || [])) if (!STOP.has(w)) freq[w] = (freq[w] || 0) + 1;
  const keywords = Object.entries(freq).sort((a, b) => b[1] - a[1]).slice(0, 6).map(e => e[0]);
  const hashtags = (caption.match(/#(\w{2,30})/g) || []).map(h => h.slice(1).toLowerCase());
  return {
    title: tr.title || (sentences[0] || 'Untitled reel').slice(0, 80),
    summary: sentences.slice(0, 3).join(' ').slice(0, 600),
    concepts: keywords.slice(0, 5).map(k => ({ name: k, explanation: '' })),
    codeSnippets: [], steps: [],
    links: (text.match(/https?:\/\/[^\s)"'>]+/g) || []).map(u => ({ url: u, label: '' })),
    topics: (hashtags.length ? hashtags : keywords).slice(0, 5),
  };
}
const arr = v => Array.isArray(v) ? v : [];
function normalise(e) {
  return {
    title: String(e.title || tr.title || 'Untitled reel').slice(0, 200),
    summary: String(e.summary || ''),
    concepts: arr(e.concepts).map(c => typeof c === 'string' ? { name: c, explanation: '' } : c).filter(c => c && c.name),
    codeSnippets: arr(e.codeSnippets || e.code_snippets).map(s => typeof s === 'string' ? { code: s } : s).filter(s => s && s.code)
      .map(s => ({ language: s.language || 'text', code: String(s.code), description: s.description || '' })),
    steps: arr(e.steps).map(String).filter(Boolean),
    links: arr(e.links).map(l => typeof l === 'string' ? { url: l, label: '' } : l).filter(l => l && /^https?:/.test(l.url || '')),
    topics: (typeof e.topics === 'string' ? e.topics.split(',') : arr(e.topics)).map(t => String(t).trim().replace(/^#/, '').toLowerCase()).filter(t => t && t.length <= 40).slice(0, 8),
  };
}

let ext = null, provider = b.provider, model = b.model, llmError = null;
if (res) {
  try {
    if (res.error) throw new Error(typeof res.error === 'string' ? res.error : (res.error.message || JSON.stringify(res.error)));
    let content;
    if (provider === 'ollama') content = res.message && res.message.content;
    else if (provider === 'openai') content = res.choices && res.choices[0] && res.choices[0].message.content;
    else content = arr(res.content).filter(c => c.type === 'text').map(c => c.text).join('');
    ext = normalise(parse(content));
  } catch (e) { llmError = String(e.message || e).slice(0, 300); }
}
const degraded = !ext;
if (!ext) { ext = normalise(heuristic()); provider = 'heuristic'; model = null; }

const concepts = ext.concepts.map(c => c.explanation ? `${c.name}: ${c.explanation}` : c.name).join('; ');
const embedText = [ext.title, ext.summary, concepts, ext.topics.join(', ')].filter(Boolean).join('. ');
return [{ json: { extraction: ext, provider, model, degraded, llmError, ollamaNote: b.ollamaNote, embedText } }];

const tr = $('Transcribe (yt-dlp + Whisper)').first().json;
const p = $('Parse extraction').first().json;
const e = $input.first().json || {};
if (!Array.isArray(e.vectors) || !Array.isArray(e.vectors[0])) {
  return [{ json: { status: 'failed', provider: p.provider, error: { code: 'embedding_failed', message: 'The embedding worker failed.', detail: JSON.stringify(e.error || e).slice(0, 500) } } }];
}
return [{ json: {
  status: 'done', provider: p.provider, model: p.model, degraded: p.degraded,
  title: tr.title, caption: tr.caption, uploader: tr.uploader, duration: tr.duration, language: tr.language,
  transcript: tr.transcript, noSpeech: tr.noSpeech, thumbnail: tr.thumbnail,
  extraction: p.extraction, embedding: e.vectors[0], embeddingModel: e.model,
} }];

const t = $input.first().json || {};
const err = t.error && t.error.code
  ? t.error
  : { code: 'worker_unavailable', message: 'The media worker could not be reached or crashed.', detail: JSON.stringify(t.error || t).slice(0, 500) };
return [{ json: { status: 'failed', error: err } }];
